/**
 * Jira Software Node - Version 1
 * Discriminator: resource=issueAttachment, operation=add
 */


interface Credentials {
  jiraSoftwareCloudApi: CredentialReference;
  jiraSoftwareServerApi: CredentialReference;
  jiraSoftwareServerPatApi: CredentialReference;
  jiraSoftwareCloudOAuth2Api: CredentialReference;
}

/** Add, remove, and get an attachment from an issue */
export type JiraV1IssueAttachmentAddParams = {
  resource: 'issueAttachment';
  operation: 'add';
  jiraVersion?: 'cloud' | 'cloudOAuth2' | 'server' | 'serverPat' | Expression<string>;
/**
 * Issue Key
 */
    issueKey: string | Expression<string>;
/**
 * Input Binary Field
 * @hint The name of the input binary field containing the file to be written
 * @default data
 */
    binaryPropertyName?: string | Expression<string>;
};

export type JiraV1IssueAttachmentAddOutput = {
  author?: {
    accountId?: string;
    accountType?: string;
    active?: boolean;
    avatarUrls?: {
      '16x16'?: string;
      '24x24'?: string;
      '32x32'?: string;
      '48x48'?: string;
    };
    displayName?: string;
    emailAddress?: string;
    self?: string;
    timeZone?: string;
  };
  content?: string;
  created?: string;
  filename?: string;
  id?: string;
  mimeType?: string;
  self?: string;
  size?: number;
};

export type JiraV1IssueAttachmentAddNode = {
  type: 'n8n-nodes-base.jira';
  version: 1;
  config: NodeConfig<JiraV1IssueAttachmentAddParams> & { credentials?: Credentials };
  output?: Items<JiraV1IssueAttachmentAddOutput>;
};